-- Supabase-style shape: an auth schema beside public, UUID keys, a cross-schema foreign key
-- from public.profiles to auth.users. Introspection runs over public only.
-- Fixture for src/test/real-world-schemas.integration.test.ts; loaded into its own database.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS auth;
CREATE TABLE auth.users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(255) UNIQUE, raw_user_meta_data jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles (id uuid PRIMARY KEY, owner_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  username text UNIQUE, full_name text, avatar_url text, website text, updated_at timestamptz,
  CONSTRAINT username_length CHECK (char_length(username) >= 3));
CREATE TABLE team_members (team_id uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'member', PRIMARY KEY (team_id, profile_id));
CREATE TABLE todos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id uuid REFERENCES auth.users(id),
  profile_id uuid REFERENCES profiles(id), task text, is_complete boolean NOT NULL DEFAULT false, inserted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid REFERENCES teams(id),
  title text NOT NULL, body text, search tsvector, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX docs_search_gin ON documents USING gin(search);
CREATE INDEX docs_meta_gin ON documents USING gin(metadata);
